  "Choose your product options and complete the personalization fields.": { es: "Elige las opciones del producto y completa los campos de personalización.", zh: "请选择商品选项并完成定制字段。" },
  "Your upload session expired. Re-upload your images before continuing.": { es: "Tu sesión de carga ha caducado. Vuelve a cargar las imágenes antes de continuar.", zh: "上传会话已过期。请重新上传图片后继续。" },
  "Your upload session or image expired. Re-upload the affected image before continuing.": { es: "Tu sesión o imagen ha caducado. Vuelve a cargar la imagen afectada antes de continuar.", zh: "上传会话或图片已过期。请重新上传受影响的图片后继续。" },
  "Wait for the current image upload to finish.": { es: "Espera a que termine la carga de la imagen actual.", zh: "请等待当前图片上传完成。" },
  "Personalization requirements changed. Review the current requirements before continuing.": { es: "Han cambiado los requisitos de personalización. Revísalos antes de continuar.", zh: "定制要求已变化。请检查当前要求后继续。" },
  "Retry the failed image upload or remove that image.": { es: "Reintenta la carga fallida o elimina esa imagen.", zh: "请重试失败的图片上传，或移除该图片。" },
  "Choose all required product options to resolve an available SKU.": { es: "Elige todas las opciones obligatorias para resolver un SKU disponible.", zh: "请选择所有必填商品选项以解析可用 SKU。" },
