  "Workshop note · 01": { es: "Nota del taller · 01", zh: "工坊便笺 · 01" },
  "Workshop note · 02": { es: "Nota del taller · 02", zh: "工坊便笺 · 02" },
  "Workshop note · 03": { es: "Nota del taller · 03", zh: "工坊便笺 · 03" },
  "Can I ask about a published product?": { es: "¿Puedo preguntar por un producto publicado?", zh: "可以咨询已发布商品吗？" },
  "Yes. Start from the current catalog or order route; this editorial page does not submit a message.": { es: "Sí. Empieza por el catálogo o la ruta de pedidos actual; esta página editorial no envía mensajes.", zh: "可以。请从当前目录或订单页面开始；此编辑页面不会提交消息。" },
