interface ReferenceLanguageContextValue {
  language: ReferenceLanguage;
  setLanguage: (language: ReferenceLanguage) => void;
  t: (english: string) => string;
}

const ReferenceLanguageContext = createContext<ReferenceLanguageContextValue | null>(null);

function isReferenceLanguage(value: string | null): value is ReferenceLanguage {
  return value === "en" || value === "es" || value === "zh";
}

export function ReferenceLanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<ReferenceLanguage>("en");

  useEffect(() => {
    try {
      const saved = window.localStorage.getItem("fig-lang");
      if (isReferenceLanguage(saved)) queueMicrotask(() => setLanguage(saved));
    } catch {
      // Local preference is optional and never an authority boundary.
    }
  }, []);

  useEffect(() => {
    document.documentElement.lang = language === "zh" ? "zh-CN" : language;
    document.documentElement.dataset.lang = language;
    try {
      window.localStorage.setItem("fig-lang", language);
    } catch {
      // Persistence is best effort only.
    }
  }, [language]);

  const value = useMemo<ReferenceLanguageContextValue>(() => ({
    language,
    setLanguage,
    t: (english) => language === "en" ? english : translations[english]?.[language] ?? english,
  }), [language]);

  return <ReferenceLanguageContext.Provider value={value}>{children}</ReferenceLanguageContext.Provider>;
}

export function useReferenceLanguage(): ReferenceLanguageContextValue {
  const value = useContext(ReferenceLanguageContext);
  return value ?? {
    language: "en" as const,
    setLanguage: () => undefined,
    t: (english: string) => english,
  };
}

export function ReferenceText({ children }: { children: string }) {
  const { t } = useReferenceLanguage();
  return <>{t(children)}</>;
}

export function ReferenceDate({ value }: { value: string }) {
  const { language } = useReferenceLanguage();
  const locale = language === "zh" ? "zh-CN" : language === "es" ? "es-ES" : "en-US";
  return <>{new Date(value).toLocaleString(locale)}</>;
}
